{

    int ret;

    struct sigaction act, oldact;

    sigset_t set, oldset;



    memset(&act, 0, sizeof(act));

    act.sa_handler = &sigbus_handler;

    act.sa_flags = 0;



    ret = sigaction(SIGBUS, &act, &oldact);

    if (ret) {

        perror("os_mem_prealloc: failed to install signal handler");

        exit(1);

    }



    /* unblock SIGBUS */

