    if (pkt->payload_len + pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len >

        ETH_MAX_IP_DGRAM_LEN) {

        return;

    }



    ip_hdr->ip_len = cpu_to_be16(pkt->payload_len +

        pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len);



