        return;

    }



    error_printf("name \"%s\"", object_class_get_name(klass));

    if (dc->bus_info) {

        error_printf(", bus %s", dc->bus_info->name);

    }

    if (dc->alias) {

        error_printf(", alias \"%s\"", dc->alias);

    }

    if (dc->desc) {

        error_printf(", desc \"%s\"", dc->desc);

    }

    if (dc->no_user) {

        error_printf(", no-user");

    }

    error_printf("\n");

}

