            mem->memory_size = 0;

            mem->guest_phys_addr = start_addr;

            mem->userspace_addr = 0;

            mem->flags = 0;



            kvm_vm_ioctl(s, KVM_SET_USER_MEMORY_REGION, mem);

        } else if (start_addr >= mem->guest_phys_addr &&

                   (start_addr + size) <= (mem->guest_phys_addr + mem->memory_size))

