        break;

    case 3:

        avctx->pix_fmt             = PIX_FMT_ARGB;

        avctx->bits_per_raw_sample = 8;



        ret = avctx->get_buffer(avctx, pic);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

            return ret;

        }



        ret = decode_argb_frame(ctx, &gb, pic);

        if (ret < 0)

            return ret;



        break;

