            if (len < 0) {

                fprintf(stderr, "Error while decoding\n");

                exit(1);

            }

            if (out_size > 0) {

                /* if a frame has been decoded, output it */

                fwrite(outbuf, 1, out_size, outfile);

            }

            size -= len;

            inbuf_ptr += len;

        }

    }



    fclose(outfile);

    fclose(f);

    free(outbuf);



    avcodec_close(c);

    free(c);

