    int16_t lp_gd[11]; // (3.12)

    int tilt_comp_coeff;

    int i;



    /* Zero-filling is necessary for tilt-compensation filter. */

    memset(lp_gn, 0, 33 * sizeof(int16_t));



    /* Calculate A(z/FORMANT_PP_FACTOR_NUM) filter coefficients. */

    for (i = 0; i < 10; i++)

