    memmove(residual, residual + subframe_size, RES_PREV_DATA_SIZE * sizeof(int16_t));



    /* short-term filter tilt compensation */

    tilt_comp_coeff = get_tilt_comp(dsp, lp_gn, lp_gd, residual_filt_buf + 10, subframe_size);



