                    case 1:

                        codec->color_range = AVCOL_RANGE_MPEG;

                        break;

                    case 2:

                        codec->color_range = AVCOL_RANGE_JPEG;

                        break;

                    default:

                        av_log(c, AV_LOG_WARNING, "ignored unknown aclr value (%d)\n", range_value);

                        break;

                    }

                    av_dlog(c, "color_range: %d\n", codec->color_range);

