            } else {

                av_log(c, AV_LOG_ERROR, "aclr not decoded - unable to add atom to extradata\n");

            }

        } else {

            av_log(c, AV_LOG_WARNING, "aclr not decoded - unexpected size %"PRId64"\n", atom.size);

        }

    }



    return ret;

}

